def transform(grid):
    h, w = len(grid), len(grid[0])

    # The panel is the large rectangular region containing the 1 background.
    panel_rows = [r for r in range(h) if sum(v == 1 for v in grid[r]) >= 5]
    panel_cols = [c for c in range(w) if sum(grid[r][c] == 1 for r in range(h)) >= 5]
    r0, r1 = min(panel_rows), max(panel_rows)
    c0, c1 = min(panel_cols), max(panel_cols)
    panel = [grid[r][c0:c1 + 1] for r in range(r0, r1 + 1)]

    outside = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 1)
               and not (r0 <= r <= r1 and c0 <= c <= c1)]

    # The most frequent non-background panel color is the drawn pattern.
    counts = {}
    for row in panel:
        for v in row:
            if v not in (0, 1):
                counts[v] = counts.get(v, 0) + 1
    motif = max(counts, key=counts.get)

    # Reflect across the anti-diagonal.
    ph, pw = len(panel), len(panel[0])
    out = [[1] * ph for _ in range(pw)]
    for r in range(ph):
        for c in range(pw):
            v = panel[r][c]
            if v == motif:
                out[pw - 1 - c][ph - 1 - r] = motif

    # Detached markers indicate which colors occupy the inset corners.
    if outside:
        minr = min(r for r, c, v in outside)
        maxr = max(r for r, c, v in outside)
        minc = min(c for r, c, v in outside)
        maxc = max(c for r, c, v in outside)
        for r, c, v in outside:
            rr = 1 if r == minr else len(out) - 2
            cc = 1 if c == minc else len(out[0]) - 2
            out[rr][cc] = v

    return out
